// InnoveXShield Forensic Report Generator

const LOGO_BASE64 = "";

export function generateHtmlReport(data, emailPayload = {}) {
    const timestamp = new Date().toLocaleString("en-US", {
        dateStyle: "full",
        timeStyle: "medium"
    });
    const reportId = "INVX-" + Math.random().toString(36).substring(2, 9).toUpperCase();

    const classification = (data.classification || data.emailVerdict || "LEGITIMATE").toUpperCase();
    const riskScore = data.risk_score !== undefined ? data.risk_score : (data.overallRiskScore || 0);
    const confidence = data.confidence || 90;
    const mlPrediction = (data.ml_prediction || "LEGITIMATE").toUpperCase();
    const mlProb = data.ml_probability !== undefined ? Math.round(data.ml_probability * 100) : 0;
    const riskLevel = data.riskLevel || (classification === "PHISHING" ? "HIGH" : (classification === "SUSPICIOUS" ? "MEDIUM" : "LOW"));

    const senderEmail = data.sender || (data.senderAnalysis ? data.senderAnalysis.email : "") || (emailPayload.sender || "Unknown Sender");
    const senderDomain = data.sender_domain || (data.senderAnalysis ? data.senderAnalysis.domain : "Unknown");
    const subject = data.subject || emailPayload.subject || "(No Subject)";

    const actionableCount = data.actionable_urls !== undefined ? data.actionable_urls : (data.urls_analyzed || 0);
    const resourceCount = data.resource_urls_ignored !== undefined ? data.resource_urls_ignored : 0;
    const suspiciousCount = data.suspicious_actionable_urls !== undefined ? data.suspicious_actionable_urls : (data.suspicious_urls || 0);

    const verdictColor = classification === "PHISHING" ? "#ef4444" : (classification === "SUSPICIOUS" ? "#f59e0b" : "#10b981");
    const verdictBg = classification === "PHISHING" ? "#fef2f2" : (classification === "SUSPICIOUS" ? "#fffbeb" : "#ecfdf5");
    const verdictBorder = classification === "PHISHING" ? "#f87171" : (classification === "SUSPICIOUS" ? "#fcd34d" : "#6ee7b7");
    const verdictIcon = classification === "PHISHING" ? "🔴" : (classification === "SUSPICIOUS" ? "🟡" : "🟢");

    let recText = "Safe to interact with. No significant threat indicators detected.";
    if (classification === "PHISHING" || data.recommended_action === "DO_NOT_CLICK") {
        recText = "🚨 CRITICAL: Do not click any links, open attachments, or enter credentials. Report and block sender immediately.";
    } else if (classification === "SUSPICIOUS" || data.recommended_action === "PROCEED_WITH_CAUTION") {
        recText = "⚠️ WARNING: Caution advised. Verify sender through an alternate verified channel before proceeding.";
    }

    const linksRows = (data.detectedLinks || []).map((link, idx) => {
        const isResource = link.urlType && link.urlType !== "ACTIONABLE";
        const linkVerdict = isResource ? "RESOURCE" : (link.verdict || "SAFE");
        const badgeColor = linkVerdict === "MALICIOUS" ? "#ef4444" : (linkVerdict === "SUSPICIOUS" ? "#f59e0b" : (isResource ? "#64748b" : "#10b981"));
        const reasonsList = (link.reasons || []).map(r => `<div>• ${r}</div>`).join("");

        return `
        <tr>
            <td style="font-weight:600;">#${idx + 1}</td>
            <td>
                <div style="font-weight:600; color:#1e293b; word-break:break-all;">${link.originalUrl}</div>
                <div style="font-size:11px; color:#64748b; margin-top:2px;">Anchor: ${link.anchorText || link.originalUrl}</div>
            </td>
            <td>
                <code>${link.domain}</code><br>
                <span style="font-size:11px; color:${link.https ? "#10b981" : "#f59e0b"};">${link.protocol || (link.https ? "HTTPS" : "HTTP")}</span>
            </td>
            <td><span class="badge" style="background:#f1f5f9; color:#334155;">${link.urlType || "ACTIONABLE"}</span></td>
            <td><span class="badge" style="background:${badgeColor}; color:#ffffff;">${linkVerdict}</span></td>
            <td style="font-weight:700;">${isResource ? "0/100" : (link.riskScore || 0) + "/100"}</td>
            <td style="font-size:11px; color:#475569;">${reasonsList || "Standard verified domain."}</td>
        </tr>`;
    }).join("");

    const indicatorsHtml = (data.indicators && data.indicators.length > 0)
        ? data.indicators.map(ind => {
            const msg = typeof ind === "object" ? ind.message : ind;
            const sev = typeof ind === "object" ? (ind.severity || "INFO") : "INFO";
            const sevColor = sev === "HIGH" ? "#ef4444" : (sev === "MEDIUM" ? "#f59e0b" : "#3b82f6");
            return `
            <div style="display:flex; align-items:flex-start; gap:8px; margin-bottom:8px; font-size:12.5px; color:#334155;">
                <span style="background:${sevColor}; color:#fff; font-weight:700; font-size:10px; padding:2px 6px; border-radius:4px; text-transform:uppercase;">${sev}</span>
                <span>${msg}</span>
            </div>`;
        }).join("")
        : "<div style=\"color:#64748b; font-size:12.5px;\">No high-risk threat indicators found.</div>";

    return `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>InnoveXShield Investigation Report - ${reportId}</title>
    <style>
        * { box-sizing: border-box; margin: 0; padding: 0; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; }
        body { background-color: #f8fafc; color: #0f172a; padding: 24px; font-size: 13px; line-height: 1.5; }
        .report-wrapper { max-width: 900px; margin: 0 auto; background: #ffffff; border-radius: 12px; border: 1px solid #e2e8f0; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.05); overflow: hidden; }
        .header { background: #0f172a; color: #ffffff; padding: 20px 28px; display: flex; justify-content: space-between; align-items: center; }
        .header-left { display: flex; align-items: center; gap: 14px; }
        .header-logo { width: 44px; height: 44px; border-radius: 8px; background: #1e293b; padding: 4px; object-fit: contain; }
        .header-title { font-size: 20px; font-weight: 800; letter-spacing: -0.5px; }
        .header-sub { font-size: 11px; color: #94a3b8; margin-top: 2px; }
        .actions-bar { display: flex; gap: 8px; }
        .btn-print { background: #3b82f6; color: #fff; border: none; padding: 8px 14px; border-radius: 6px; font-weight: 600; font-size: 12px; cursor: pointer; }
        .btn-print:hover { background: #2563eb; }
        .content { padding: 28px; }
        .meta-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-bottom: 24px; background: #f1f5f9; padding: 14px; border-radius: 8px; }
        .meta-item { font-size: 11px; }
        .meta-label { color: #64748b; font-weight: 600; text-transform: uppercase; font-size: 10px; margin-bottom: 2px; }
        .meta-value { color: #0f172a; font-weight: 700; word-break: break-all; }
        .verdict-card { background: ${verdictBg}; border: 2px solid ${verdictBorder}; border-radius: 10px; padding: 18px 24px; display: flex; justify-content: space-between; align-items: center; margin-bottom: 24px; }
        .verdict-title { font-size: 22px; font-weight: 900; color: ${verdictColor}; display: flex; align-items: center; gap: 10px; }
        .score-pill { background: ${verdictColor}; color: #ffffff; padding: 6px 14px; border-radius: 20px; font-weight: 800; font-size: 16px; }
        .section-card { border: 1px solid #e2e8f0; border-radius: 8px; padding: 16px 20px; margin-bottom: 20px; }
        .section-title { font-size: 14px; font-weight: 800; color: #1e293b; margin-bottom: 12px; display: flex; align-items: center; gap: 8px; border-bottom: 1px solid #f1f5f9; padding-bottom: 8px; }
        .stats-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; text-align: center; }
        .stat-box { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 6px; padding: 10px; }
        .stat-num { font-size: 18px; font-weight: 800; color: #0f172a; }
        .stat-label { font-size: 10.5px; color: #64748b; margin-top: 2px; }
        table { width: 100%; border-collapse: collapse; font-size: 12px; }
        th { text-align: left; padding: 8px 10px; background: #f8fafc; border-bottom: 2px solid #e2e8f0; color: #475569; font-weight: 700; }
        td { padding: 10px; border-bottom: 1px solid #f1f5f9; vertical-align: top; }
        .badge { display: inline-block; padding: 2px 8px; border-radius: 12px; font-size: 10px; font-weight: 700; text-transform: uppercase; }
        .footer { text-align: center; padding: 16px; background: #f8fafc; border-top: 1px solid #e2e8f0; font-size: 11px; color: #64748b; }
        @media print {
            body { padding: 0; background: #fff; }
            .report-wrapper { border: none; box-shadow: none; max-width: 100%; }
            .btn-print { display: none; }
        }
    </style>
</head>
<body>
    <div class="report-wrapper">
        <!-- Header -->
        <div class="header">
            <div class="header-left">
                <img src="data:image/png;base64," class="header-logo" alt="InnoveXShield" />
                <div>
                    <div class="header-title">INNOVEXSHIELD</div>
                    <div class="header-sub">Threat Intelligence & Phishing Forensic Report</div>
                </div>
            </div>
            <div class="actions-bar">
                <button onclick="window.print()" class="btn-print">🖨️ Print / Save PDF</button>
            </div>
        </div>

        <!-- Content -->
        <div class="content">
            <!-- Metadata Grid -->
            <div class="meta-grid">
                <div class="meta-item">
                    <div class="meta-label">Report ID</div>
                    <div class="meta-value">${reportId}</div>
                </div>
                <div class="meta-item">
                    <div class="meta-label">Date & Time</div>
                    <div class="meta-value">${timestamp}</div>
                </div>
                <div class="meta-item">
                    <div class="meta-label">Sender</div>
                    <div class="meta-value">${senderEmail}</div>
                </div>
                <div class="meta-item">
                    <div class="meta-label">Sender Domain</div>
                    <div class="meta-value">${senderDomain}</div>
                </div>
            </div>

            <!-- Verdict Card -->
            <div class="verdict-card">
                <div>
                    <div class="verdict-title">${verdictIcon} ${classification}</div>
                    <div style="font-size: 12px; color: #475569; margin-top: 4px;">
                        Confidence: <strong>${confidence}%</strong> • Risk Level: <strong>${riskLevel}</strong>
                    </div>
                </div>
                <div class="score-pill">Risk: ${riskScore}/100</div>
            </div>

            <!-- ML Analysis & Metric Stats -->
            <div class="section-card">
                <div class="section-title">🤖 Gradient Boosting ML Model & URL Metrics</div>
                <div class="stats-grid">
                    <div class="stat-box">
                        <div class="stat-num">${actionableCount}</div>
                        <div class="stat-label">Actionable Links</div>
                    </div>
                    <div class="stat-box">
                        <div class="stat-num">${resourceCount}</div>
                        <div class="stat-label">Resources Excluded</div>
                    </div>
                    <div class="stat-box">
                        <div class="stat-num">${suspiciousCount}</div>
                        <div class="stat-label">Suspicious Links</div>
                    </div>
                    <div class="stat-box">
                        <div class="stat-num" style="color:${mlProb > 50 ? "#ef4444" : "#10b981"};">${mlProb}%</div>
                        <div class="stat-label">ML Phish Probability</div>
                    </div>
                </div>
            </div>

            <!-- Subject & Summary -->
            <div class="section-card">
                <div class="section-title">📋 Executive Summary & Explanation</div>
                <p style="font-weight:700; color:#1e293b; margin-bottom:4px;">Subject: ${subject}</p>
                <p style="color:#475569; font-size:12.5px;">${data.explanation || "No detailed anomaly detected."}</p>
            </div>

            <!-- Threat Indicators -->
            <div class="section-card">
                <div class="section-title">⚠️ Threat Indicators & Anomaly Detection</div>
                ${indicatorsHtml}
            </div>

            <!-- URL Breakdown Table -->
            <div class="section-card">
                <div class="section-title">🔗 Detected Link Investigation Breakdown (${(data.detectedLinks || []).length})</div>
                <div style="overflow-x: auto;">
                    <table>
                        <thead>
                            <tr>
                                <th>#</th>
                                <th>URL & Anchor</th>
                                <th>Domain / Protocol</th>
                                <th>Type</th>
                                <th>Verdict</th>
                                <th>Risk</th>
                                <th>Observations</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${linksRows || "<tr><td colspan=\"7\" style=\"text-align:center; color:#64748b;\">No links found in target.</td></tr>"}
                        </tbody>
                    </table>
                </div>
            </div>

            <!-- Recommendation -->
            <div class="section-card" style="background:#f8fafc; border-left:4px solid #3b82f6;">
                <div class="section-title">💡 Security Recommendation</div>
                <p style="font-weight:700; color:#0f172a;">${recText}</p>
            </div>
        </div>

        <!-- Footer -->
        <div class="footer">
            Generated by <strong>InnoveXShield</strong> Cyber Defense Platform • Powered by 30-Feature Gradient Boosting Classifier
        </div>
    </div>
</body>
</html>`;
}

export function downloadReport(data, emailPayload = {}) {
    try {
        const htmlContent = generateHtmlReport(data, emailPayload);
        const blob = new Blob([htmlContent], { type: "text/html;charset=utf-8" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        const filename = `InnoveXShield_Report_${new Date().toISOString().slice(0,10)}_${Math.random().toString(36).substring(2,6).toUpperCase()}.html`;
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    } catch (err) {
        console.error("[InnoveXShield] Error generating report:", err);
    }
}
